You right! I've oversimplified the example and this result in issue gone. Sorry!
It turns out this issue happens together with require('lazy').install():wait(). Please try to reproduce it this way:

Have lazy installed in usual place.
Create this lazy-minit.lua:

local lazypath = vim.fn.stdpath 'data' .. '/lazy/lazy.nvim'
vim.opt.rtp:prepend(lazypath)

require('lazy').setup {
    spec = {
        { 'folke/lazy.nvim', version = '*' },
    },
}
require('lazy').install():wait() -- REMOVING THIS LINE FIXES THE ISSUE WITH child.type_keys RACE

Run this test:

local assert = require 'luassert'

local child = require('mini.test').new_child_neovim()
teardown(child.stop)

local function child_lines()
    return child.api.nvim_buf_get_lines(0, 0, -1, true)
end

local lines = { 'Lorem', 'ipsum', 'dolor', 'sit', 'amet' }

before_each(function()
    child.restart { '-u', 'lazy-minit.lua' }
    child.api.nvim_buf_set_lines(0, 0, -1, true, lines)
end)

it('should work', function()
    child.type_keys(16, 'jdd') -- On my system wait=16 is racy 50/50%, wait=10 is almost always fail, wait=100 always succeed
    assert.same({ 'Lorem', 'dolor', 'sit', 'amet' }, child_lines())
end)
